// entry (base64 of the same file passed to Buffer.from(...).toString('base64'))
// whenever tshirt-black.jpg changes or a new product is added.
export const GARMENT_PHOTOS_BASE64: Record<string, string> = {
  "camiseta-preta":
    "",
};
